*Meanwhile, the product development continued... and the Test Engineer found themselves staring at a checkout component of considerable complexity.*

The story so far: in the beginning, the project was created. This has made a lot of people very angry and been widely regarded as a bad move. But the tests, dear viewer, the tests shall guide us through.

```typescript
// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// And now for something completely different: the mocks
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Holy Grail', price: 99.99 },
  { id: '2', name: 'Shrubbery', price: 24.99 }
];

const renderCheckout = (items = mockItems, onComplete = vi.fn()) => {
  return render(
    <CartProvider value={{ items, total: 124.98, clearCart: mockClearCart }}>
      <PaymentProvider value={{ processPayment: mockProcessPayment }}>
        <Checkout onComplete={onComplete} onCancel={vi.fn()} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
    renderCheckout(mockItems, onComplete);

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Camelot Lane');
    await user.type(screen.getByLabelText(/city/i), 'Camelot');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'King Arthur');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/holy grail/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText(/ORD-12345/)).toBeInTheDocument();
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-12345');
  });
});

describe('Checkout - Form Validation', () => {
  it('displays shipping validation errors for empty fields', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
  });

  it('validates ZIP code format', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });
});

describe('Checkout - Edge Cases', () => {
  it('displays empty cart message when no items', () => {
    renderCheckout([]);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    expect(screen.getByRole('button', { name: /continue shopping/i })).toBeInTheDocument();
  });

  it('handles payment failure gracefully', async () => {
    const user = userEvent.setup();
    mockProcessPayment.mockRejectedValue(new Error('Card declined'));
    // ... navigate to review step, then:

    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
  });
});
```

